'use strict';

class TokenBucket {
  constructor({ capacity, refillPerSecond, now } = {}) {
    if (typeof capacity !== 'number' || !isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }
    if (now !== undefined && typeof now !== 'function') {
      throw new RangeError('now must be a function');
    }

    this._capacity = capacity;
    this._rate = refillPerSecond;
    this._now = typeof now === 'function' ? now : () => Date.now();
    // Kovayı dolu başlat (dolu = capacity).
    this._tokens = capacity;
    this._lastTime = this._now();
  }

  // _refill: _lastTime'dan bu yana geçen sürede eklenen jetonları uygular.
  // Saat geri giderse (t < _lastTime) hiçbir şey eklenmez; _lastTime referans kalır.
  _refill() {
    const t = this._now();
    if (t < this._lastTime) return;
    const dt = t - this._lastTime;
    if (dt > 0) {
      this._tokens = Math.min(this._capacity, this._tokens + (dt / 1000) * this._rate);
    }
    this._lastTime = t;
  }

  available() {
    this._refill();
    return this._tokens;
  }

  tryTake(n = 1) {
    this._validateN(n);
    this._refill();
    if (this._tokens >= n) {
      this._tokens -= n;
      return true;
    }
    return false;
  }

  msUntil(n = 1) {
    this._validateN(n);
    this._refill();
    if (this._tokens >= n) return 0;
    if (n > this._capacity || this._rate === 0) return Infinity;
    return Math.ceil(((n - this._tokens) / this._rate) * 1000);
  }

  _validateN(n) {
    if (typeof n !== 'number' || !isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }
  }
}

module.exports = { TokenBucket };

