code = r'''
const { TokenBucket } = require('./kova.js');
let pass = 0, fail = 0;
function eq(a, b, msg) {
  const ok = Object.is(a, b) || (typeof a === 'number' && typeof b === 'number' && Math.abs(a-b) < 1e-9);
  if (ok) pass++; else { fail++; console.log('FAIL: ' + msg + ' got=' + a + ' want=' + b); }
}

// dolu başlar
let t = 0;
let b = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: () => t });
eq(b.available(), 10, 'full start');

// tryTake
eq(b.tryTake(), true, 'take 1');
eq(b.tryTake(4), true, 'take 4');
eq(b.available(), 5, 'avail after takes');

// süre dolması
t += 1000; // 1s => +2
eq(b.available(), 7, 'after 1s');
t += 250; // 0.25s => +0.5
eq(b.available(), 7.5, 'after 0.25s');

// kapasite üst sınır
t += 100000;
eq(b.available(), 10, 'capped at capacity');

// saat geri giderse
const t2 = 5000;
const b2 = new TokenBucket({ capacity: 5, refillPerSecond: 1, now: () => t2 });
b2.tryTake(3); // 2 kalır
const t3 = 4000; // geri
const b3 = new TokenBucket({ capacity: 5, refillPerSecond: 10, now: () => t3 });
eq(b3.available(), 5, 'full');
eq(b3.tryTake(2), true, 'take2');
t3 - 1000; // geride
eq(b3.available(), 3, 'time goes back no add');
t3 = 5000; // ileri 1s => +10 -> capped
eq(b3.available(), 5, 'refill capped after back');

// msUntil
const b4 = new TokenBucket({ capacity: 10, refillPerSecond: 1000, now: () => 0 });
// 1000 jeton/sn => 1 jeton/ms... 1000 jeton/sn = 1 jeton / ms. 
b4.tryTake(10); // 0
eq(b4.msUntil(1), 1, '1 token at 1000/s = 1ms');
eq(b4.msUntil(10), 10, '10 tokens = 10ms');
eq(b4.msUntil(0.5), 1, '0.5 ceil to 1ms');

// yeterliyse 0
eq(b4.available(), 0, 'zero avail');
const b5 = new TokenBucket({ capacity: 5, refillPerSecond: 1, now: () => 0 });
eq(b5.msUntil(3), 0, 'enough now => 0');

// n > capacity => Infinity
eq(b4.msUntil(11), Infinity, 'n>capacity Infinity');

// rate 0 ve yetmiyor => Infinity
const b6 = new TokenBucket({ capacity: 5, refillPerSecond: 0, now: () => 0 });
b6.tryTake(5);
eq(b6.available(), 0, 'b6 zero');
eq(b6.msUntil(1), Infinity, 'rate 0 => Infinity');

// RangeError testleri
function throws(fn, msg) {
  try { fn(); fail++; console.log('FAIL(no throw): ' + msg); }
  catch (e) {
    if (e instanceof RangeError) pass++; else { fail++; console.log('FAIL(wrong err ' + (e && e.name) + '): ' + msg); }
  }
}
throws(() => new TokenBucket({ capacity: 0, refillPerSecond: 1 }), 'capacity 0');
throws(() => new TokenBucket({ capacity: -1, refillPerSecond: 1 }), 'capacity neg');
throws(() => new TokenBucket({ capacity: Infinity, refillPerSecond: 1 }), 'capacity inf');
throws(() => new TokenBucket({ capacity: '10', refillPerSecond: 1 }), 'capacity str');
throws(() => new TokenBucket({ capacity: NaN, refillPerSecond: 1 }), 'capacity NaN');
throws(() => new TokenBucket({ capacity: 10, refillPerSecond: -0.1 }), 'rate neg');
throws(() => new TokenBucket({ capacity: 10, refillPerSecond: '2' }), 'rate str');
throws(() => new TokenBucket({ capacity: 10, refillPerSecond: NaN }), 'rate NaN');
// n hataları
throws(() => b5.tryTake(0), 'tryTake 0');
throws(() => b5.tryTake(-1), 'tryTake neg');
throws(() => b5.tryTake(Infinity), 'tryTake inf');
throws(() => b5.tryTake(NaN), 'tryTake NaN');
throws(() => b5.msUntil(0), 'msUntil 0');
throws(() => b5.msUntil(-2), 'msUntil neg');
throws(() => b5.msUntil(Infinity), 'msUntil inf');

// default n=1
const b7 = new TokenBucket({ capacity: 2, refillPerSecond: 0, now: () => 0 });
eq(b7.tryTake(), true, 'default n=1 ok');
eq(b7.tryTake(), true, 'default n=1 ok2');
eq(b7.tryTake(), false, 'default n=1 false');
eq(b7.available(), 0, 'b7 avail 0');

// kesirli refill tam sınırı: 1 jeton/s, 0.5s => 0.5
const tt = 0;
const b8 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: () => tt });
b8.tryTake(10);
tt = 500;
eq(b8.available(), 0.5, 'half token');

console.log('\npass=' + pass + ' fail=' + fail);
process.exit(fail ? 1 : 0);
'''
with open('_test.js', 'w', encoding='utf-8') as f:
    f.write(code)

